import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import gap_labels

class GapTests(unittest.TestCase):
    def setUp(self):
        self.opening = parse_span("09:00-17:00")

    def _labels(self, *worked):
        spans = [parse_span(text) for text in worked]
        return gap_labels(spans, self.opening)

    def test_nothing_worked_is_one_gap(self):
        expected = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(self._labels(), expected)

    def test_gap_between_shifts(self):
        labels = self._labels("09:00-12:00", "13:00-17:00")
        expected = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(labels, expected)

    def test_gaps_at_both_ends(self):
        labels = self._labels("10:00-12:00")
        expected = [
            "gap 09:00-10:00 (60 min)",
            "gap 12:00-17:00 (300 min)"
        ]
        self.assertEqual(labels, expected)

    def test_overlap_and_touch_leave_one_gap(self):
        labels = self._labels(
            "09:00-12:00", "11:00-13:00", "13:00-14:00"
        )
        expected = ["gap 14:00-17:00 (180 min)"]
        self.assertEqual(labels, expected)

    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(self._labels("09:00-17:00"), [])

    def test_span_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            self._labels("08:30-10:00")
        with self.assertRaises(ValueError):
            self._labels("16:00-17:30")
